import java.io.*;
import java.util.*;

public class Main {
  public static void main(String[] args) throws IOException {
    BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    PrintWriter writer = new PrintWriter(System.out);
    new Solver().execute(reader, writer);
    writer.close();
  }

  static class Solver {
    void execute(BufferedReader br, PrintWriter pw) throws IOException {
      int n = Integer.parseInt(br.readLine());
      String line = br.readLine();
      char[] s = line.toCharArray();
      int[] beauty = new int[n];
      String[] parts = br.readLine().split(" ");
      int totalBeauty = 0;
      for (int i = 0; i < n; i++) {
        beauty[i] = Integer.parseInt(parts[i]);
        totalBeauty += beauty[i];
      }

      List<Integer> pairs = new ArrayList<>();
      int[] freq = new int[128];
      char maxChar = 'a';

      for (int i = 0; i < n / 2; i++) {
        if (s[i] == s[n - 1 - i]) {
          pairs.add(i);
          if (++freq[s[i]] > freq[maxChar]) {
            maxChar = s[i];
          }
        }
      }

      int result = totalBeauty;
      for (int idx : pairs) {
        result -= Math.min(beauty[idx], beauty[n - 1 - idx]);
      }

      if (freq[maxChar] > pairs.size() / 2) {
        List<Integer> penalties = new ArrayList<>();
        for (int i = 0; i < n / 2; i++) {
          if (s[i] != s[n - 1 - i] && s[i] != maxChar && s[n - 1 - i] != maxChar) {
            penalties.add(Math.min(beauty[i], beauty[n - 1 - i]));
          }
        }
        Collections.sort(penalties);
        int rem = 2 * freq[maxChar] - pairs.size();
        for (int i = 0; i < rem; i++) {
          result -= penalties.get(i);
        }
      }

      pw.println(result);
    }
  }
}
