#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    vector<int> beauty(n);
    for (int i = 0; i < n; i++) {
        cin >> beauty[i];
    }
    int totalBeauty = accumulate(beauty.begin(), beauty.end(), 0);
    vector<int> pairs;
    vector<int> freq(128, 0);
    char maxChar = 'a';

    for (int i = 0; i < n / 2; i++) {
        if (s[i] == s[n - 1 - i]) {
            pairs.push_back(i);
            if (++freq[s[i]] > freq[maxChar]) {
                maxChar = s[i];
            }
        }
    }

    int result = totalBeauty;
    for (int idx : pairs) {
        result -= min(beauty[idx], beauty[n - 1 - idx]);
    }

    if (freq[maxChar] > (int)pairs.size() / 2) {
        vector<int> penalties;
        for (int i = 0; i < n / 2; i++) {
            if (s[i] != s[n - 1 - i] && s[i] != maxChar && s[n - 1 - i] != maxChar) {
                penalties.push_back(min(beauty[i], beauty[n - 1 - i]));
            }
        }
        sort(penalties.begin(), penalties.end());
        int rem = 2 * freq[maxChar] - (int)pairs.size();
        for (int i = 0; i < rem; i++) {
            result -= penalties[i];
        }
    }

    cout << result << "\n";
    return 0;
}
